              onClick={handleCriarSetor} disabled={criando || !novoNome.trim()}>
              {criando ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
              <span className="hidden sm:inline">Criar</span>
            </Button>
          </div>

          <div className="pt-2">
            {isLoading ? (
              <div className="flex justify-center items-center h-32">
                <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
              </div>
            ) : (
              <div className="max-h-[55vh] overflow-y-auto space-y-2 pr-1">
                {setores.length === 0 && (
                  <p className="text-center text-sm text-muted-foreground py-8">
                    Nenhum setor cadastrado. Crie o primeiro acima.
                  </p>
                )}
                {setores.map((setor) => (
                  <div key={setor.nome} className="bg-white/40 dark:bg-black/20 border border-[#57715B]/10 rounded-xl p-3 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <span className="font-semibold text-[#2D362E] dark:text-[#E6DCCF] truncate">{setor.nome}</span>
                      <Badge className="bg-[#57715B]/10 text-[#57715B] rounded-full text-xs shrink-0 border-0">
                        {setor.itensAtivos} {setor.itensAtivos === 1 ? 'item' : 'itens'}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 w-full sm:w-auto">
                      <Select onValueChange={(value) => handleMoverItens(setor.nome, value)}
                        disabled={setor.itensAtivos === 0 || movendo[setor.nome]} value="">
                        <SelectTrigger data-mia-action="mover_itens_setor"
                          className="w-full sm:w-[180px] bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-9 text-xs">
                          {movendo[setor.nome] ? (
                            <div className="flex items-center gap-2"><Loader2 className="h-3 w-3 animate-spin" /><span>Movendo...</span></div>
                          ) : (
                            <SelectValue placeholder="Mover itens para..." />
                          )}
                        </SelectTrigger>
                        <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl">
                          {setores.filter((s) => s.nome !== setor.nome).map((destino) => (
                            <SelectItem key={destino.nome} value={destino.nome} className="focus:bg-[#57715B]/10 rounded-lg">
                              {destino.nome}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                      <Button variant="ghost" size="icon" data-mia-action="excluir_setor"
                        aria-label={setor.itensAtivos > 0 ? 'Mova os itens antes de excluir' : 'Excluir setor ' + setor.nome}
                        className="h-9 w-9 rounded-xl text-red-500 hover:bg-red-500/10 hover:text-red-600 shrink-0"
                        onClick={() => setSetorParaExcluir(setor)} disabled={setor.itensAtivos > 0}
                        title={setor.itensAtivos > 0 ? 'Mova os itens antes de excluir' : 'Excluir setor'}>
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={!!setorParaExcluir} onOpenChange={(isOpen) => !isOpen && setSetorParaExcluir(null)}>
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-[#2D362E] dark:text-[#E6DCCF]">Excluir setor?</AlertDialogTitle>
            <AlertDialogDescription>
              O setor <span className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">{setorParaExcluir?.nome}</span> sera removido permanentemente.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel asChild><Button variant="ghost" className="rounded-xl">Cancelar</Button></AlertDialogCancel>
            <AlertDialogAction className="bg-red-600 hover:bg-red-700 text-white rounded-xl"
              onClick={handleConfirmarExclusao} disabled={excluindo}>
              {excluindo && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
